const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/workflows/presets',
  qs: {
    per_page: 'SOME_INTEGER_VALUE',
    'filters[tool_type]': 'SOME_STRING_VALUE',
    'filters[tool_subtype]': 'SOME_STRING_VALUE',
    'filters[is_default]': 'SOME_BOOLEAN_VALUE',
    'filters[is_valid]': 'SOME_BOOLEAN_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/workflows/presets?per_page=SOME_INTEGER_VALUE&filters%5Btool_type%5D=SOME_STRING_VALUE&filters%5Btool_subtype%5D=SOME_STRING_VALUE&filters%5Bis_default%5D=SOME_BOOLEAN_VALUE&filters%5Bis_valid%5D=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

